-- WoW Forever world data from Everlake, 24-25 November (buildthehomelab/wow-everlake-world-data ea2b4235..dd3a74f, GPL-3.0,
-- used with credit and thanks). Their facts come from Icy Veins' WoW Forever database, Wowhead Forever, EG Link (CC BY) and
-- QuestieDB (GPL-3.0). Everything up to 1b7b651 was already in our world (2026_11_24_95, 2026_11_25_20/21).
--   Loot: live drop rates on about 1,600 loot tables (only rows from the QuestieDB import or the November sniffs that sit at three
--     times the live rate or more, on creatures with 300+ recorded kills); Galestrider and Ornery Galestrider loot and skinning;
--     live drops our tables lacked (cloth, beast parts, 465 pairs at 3% or more); 16 Forever items on Classic rares at 35%.
--   Spawns: rares Old Rusthowl 263935, Soul of Tanaris 8206, Duke Ragereaver 10820 (guids 920019400-920019420, pools
--     920000202-920000204); vendors and trainers in the Shen'dralar town, Hillsbrad and Aerie Peak; Redridge camp crates;
--     Twilight Brute 261710; five Ogre Miners for Rise Up! 95432; Strange Orb 409289 for A Strange Artifact 78088.
--   Removed: restore objects standing inside their live twin (chairs, braziers, anvils; only where the twin still stands),
--     second copies of named NPCs, the Camp Tents at the adventurer camps.
--   Quests: kill credit for hidden credit markers, Silvia's Sword 79363 for Alliance, quest levels and money from live records,
--     6 live creature names, Open the Maw after Dragonmaw Rumors, 3 missing quests, quest texts (Forge 311-317).
--   Pets: four Forever beasts tameable.
-- Each part only touches rows still in the state it expects, so it is safe to run twice. Their row log table is left out.


-- Everlake 2026_11_24_900 forge_00311_import
START TRANSACTION;
DROP TEMPORARY TABLE IF EXISTS `ev1126_forge_stage`;
CREATE TEMPORARY TABLE `ev1126_forge_stage` SELECT `ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild` FROM `quest_offer_reward` LIMIT 0;
DELETE s FROM `ev1126_forge_stage` s JOIN `quest_offer_reward` x ON x.`ID` <=> s.`ID`;
DROP TEMPORARY TABLE IF EXISTS `ev1126_forge_stage`;
CREATE TEMPORARY TABLE `ev1126_forge_stage` SELECT `ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild` FROM `quest_request_items` LIMIT 0;
DELETE s FROM `ev1126_forge_stage` s JOIN `quest_request_items` x ON x.`ID` <=> s.`ID`;
DROP TEMPORARY TABLE IF EXISTS `ev1126_forge_stage`;
CREATE TEMPORARY TABLE `ev1126_forge_stage` SELECT `Entry`, `ItemType`, `Item`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment` FROM `gameobject_loot_template` LIMIT 0;
DELETE s FROM `ev1126_forge_stage` s JOIN `gameobject_loot_template` x ON x.`Entry` <=> s.`Entry` AND x.`ItemType` <=> s.`ItemType` AND x.`Item` <=> s.`Item`;
UPDATE `creature_loot_template` SET `Chance` = 8.86 WHERE `Entry` = 16080 AND `ItemType` = 0 AND `Item` = 22046 AND ABS(`Chance` - 4.53) < 0.005 /* refresh */;
DROP TEMPORARY TABLE IF EXISTS `ev1126_forge_stage`;
COMMIT;


