  AND NOT EXISTS (SELECT 1 FROM `skinning_loot_template` k WHERE k.`Entry` = s.`entry`);
SELECT s.`entry`, 0, s.`item`, s.`chance`, 0, 1, 0, 1, 1, s.`comment` FROM `ev1126_live_skin` s WHERE s.`ok` = 1;
UPDATE `creature_template_difficulty` d SET d.`SkinLootID` = d.`Entry`
WHERE d.`DifficultyID` = 0 AND d.`SkinLootID` = 0 AND d.`Entry` IN (SELECT DISTINCT s.`entry` FROM `ev1126_live_skin` s WHERE s.`ok` = 1);
